// Builds Figma-format binary fixtures from scratch: an independently written subset schema with the field
// names the importer reads, a scene authored here (no Figma file content), encoded with our kiwi writer,
// wrapped as clipboard HTML and as a .fig zip with an embedded PNG. Used by tests/figma-binary.cjs and
// tests/figma-paste.cjs.
import zlib from "node:zlib";
import { createHash } from "node:crypto";
import { encodeScene, buildClipboardHtml, writeZip } from "../../integrations/figma-kiwi.mjs";
import { commandsFromPath } from "../../integrations/figma-scene.mjs";

const enumDef = (name, values) => ({
  name,
  kind: "ENUM",
  fields: values.map((v, i) => ({ name: v, type: "uint", isArray: false, value: i })),
});
// Fields: [name, type, isArray?]; struct fields keep order, message fields get ids 1..n.
const struct = (name, fields) => ({
  name,
  kind: "STRUCT",
  fields: fields.map(([n, t, a], i) => ({ name: n, type: t, isArray: !!a, value: i + 1 })),
});
const message = (name, fields) => ({
  name,
  kind: "MESSAGE",
  fields: fields.map(([n, t, a], i) => ({ name: n, type: t, isArray: !!a, value: i + 1 })),
});

