export function clipboardHtml({ compression = "deflate" } = {}) {
  return buildClipboardHtml(
    { fileKey: "FixtureKey123", pasteID: 42, dataType: "scene" },
    encodeScene(schema, buildScene(), { compression }),
  );
}
export function figFile() {
  const png = tinyPng(),
    hash = createHash("sha1").update(png).digest();
  const canvas = encodeScene(schema, buildScene({ imageHash: new Uint8Array(hash) }), {
    compression: "deflate",
  });
  return {
    bytes: writeZip([
      ["canvas.fig", canvas],
      ["meta.json", JSON.stringify({ file_name: "Fixture design", version: 1 })],
      ["thumbnail.png", png],
      [`images/${hash.toString("hex")}`, png],
    ]),
    png,
  };
}
